// R4g-mcp MA-7: the transcript mount of the 2.42304.0 MCP App / Visualize widget card (VX = memo(kQe), generated by
// scripts/extract-mcp-app-card.mjs into src/generated/mcp-app-card, MA-6).
//
// Official mount (v1/c96d752d0-BOCqU7c2.js, pinned in the generated manifest's callSites):
//   KBe  a tool the session's isMcpAppTool (cef1e6037 lt) accepts is its own "mcp_app" row; UV.mcp_app rolls up
//        "stands-alone", so the call is never a tool group member.
//   m2e  solo row of an owned session: b(VX,{tool,sessionRef,onPrefillComposer}) — VX falls back to Uz, the engine's row.
//   e0   row inside a group: b(VX,{tool,sessionRef,onPrefillComposer,fallback}) — the group's own row as fallback.
// The host: every local session is owned (a core the app runs). The fallback is always the host's own generic tool row
// (source-session.jsx), which is what Uz draws for an MCP call in the host, so kQe's every skip reason (server unknown,
// no ui:// resource, hash pending, pending approval, init error, chunk failed…) shows that row, never a placeholder.
//
// Data the card's adapters read (source-mcp-app-card-adapters.jsx mcpAppCardHost), fed from here:
//   servers    MA-4 desktop:call "mcp-app:servers" {sessionId} → mcp-app-model sessionMcpAppServers → setSessionServers;
//              listed once per session and again for each MCP server name the last listing did not cover. A failed
//              listing, or one with a core server still starting, is asked again on the official repoll schedule
//              (CFJssAFf schedulePendingMcpRepoll XA=[2e3,5e3,15e3,3e4,6e4]); after that schedule runs out, a row that
//              mounts more than 5 s after the last try asks again (warmSession: sdkMcpLastPollAt older than 5e3).
//   approvals  the host's pending approvals of the row's call → setToolApprovals (kQe pending_approval).
//   client     the MA-6 bridge client as is (tools/call {name}, which MA-4 reads since R4i-mcp MC1).
//   context    ui/update-model-context lands in the card's shared-28 store; noteMcpAppSendContext hands the session's
//              states to MA-4 when the composer sends (c6b8adeaf getModelContextStates → LocalSessions sendMessage).
//   prefill    ui/message → onPrefillComposer: the Code transcript only fills the composer (official H_); main.jsx
//              registers its composer per session through useMcpAppTranscript.
import React, { useEffect, useMemo, useRef, useSyncExternalStore } from 'react';
import { mcpAppCardHost, useSessionMcpState, findMcpAppToolServer } from './source-mcp-app-card-adapters.jsx';
import { groupAroundMcpAppRows, mcpAppRowKind, mcpCallOf, officialToolName, sessionMcpAppServers, toMcpAppTool, MCP_APP_ROW } from './mcp-app-model.mjs';
import './source-mcp-app.css';

// ---- the card module (about 171 KB of generated originals) loads the first time a row needs it.
const cardListeners = new Set();
let cardModule = null, cardLoad = null;
const notifyCard = () => { for (const listener of cardListeners) listener(); };
const subscribeCard = listener => { cardListeners.add(listener); return () => cardListeners.delete(listener); };
/** Load the generated card (VX). Resolves with the module; a failed load is retried by the next row that needs it. */
export function loadMcpAppCard() {
  cardLoad ??= import('./generated/mcp-app-card/tool-card.mjs').then(module => { cardModule = module; notifyCard(); return module; },
    error => { cardLoad = null; throw error; });
  return cardLoad;
}
function useCardModule(wanted) {
  const module = useSyncExternalStore(subscribeCard, () => cardModule, () => cardModule);
  useEffect(() => { if (wanted && !cardModule) loadMcpAppCard().catch(error => console.warn('[MCP App] card failed to load', error)); }, [wanted]);
  return module;
}

// ---- servers: MA-4 mcp-app:servers per session.
// CFJssAFf XA: the repoll delays while a server is pending; warmSession re-reads a session whose last poll is older.
export const MCP_APP_REPOLL_MS = Object.freeze([2e3, 5e3, 15e3, 3e4, 6e4]);
export const MCP_APP_WARM_REPOLL_MS = 5e3;
const listings = new Map(); // sessionId → {pending, segments, settled, attempt, timer, lastAt}
const now = () => Date.now();
function desktopCall() {
  const call = globalThis.window?.desktop?.call;
  return typeof call === 'function' ? call : null;
}
// A listing that did not settle the session's servers: the call failed, the core's list failed (read_failed), the core
// was not connected yet (not_connected without core_unsupported; officially the init poll follows the query), or a core
// server is still starting (CFJssAFf schedulePendingMcpRepoll: some status "pending").
const unsettled = reply => reply === null || reply?.core?.unavailable === 'read_failed' || reply?.core?.pending === true
  || (reply?.core?.unavailable === 'not_connected' && reply?.core?.reason === undefined);
function scheduleRepoll(sessionId, entry) {
  if (entry.timer !== null) return;
  const delay = MCP_APP_REPOLL_MS[entry.attempt];
  if (delay === undefined) return;
  entry.timer = setTimeout(() => {
    entry.timer = null;
    entry.attempt += 1;
    if (listings.get(sessionId) === entry) listServers(sessionId);
  }, delay);
}
function listServers(sessionId) {
  const call = desktopCall();
  if (!call || !sessionId) return null;
  let entry = listings.get(sessionId);
  if (!entry) listings.set(sessionId, entry = { pending: null, segments: new Set(), settled: false, attempt: 0, timer: null, lastAt: 0 });
  if (entry.pending) return entry.pending;
  entry.lastAt = now();
  entry.pending = Promise.resolve().then(() => call('mcp-app:servers', { sessionId }))
    .then(reply => { mcpAppCardHost.setSessionServers(sessionId, sessionMcpAppServers(reply)); return reply; })
    .catch(error => { console.warn('[MCP App] server listing failed', error?.message ?? error); return null; })
    .then(reply => {
      if (listings.get(sessionId) !== entry) return reply;
      entry.settled = !unsettled(reply);
      if (entry.settled) { entry.attempt = 0; if (entry.timer !== null) { clearTimeout(entry.timer); entry.timer = null; } }
      else scheduleRepoll(sessionId, entry);
      return reply;
    })
    .finally(() => { entry.pending = null; });
  return entry.pending;
}
/**
 * List the session's MCP App servers once, and again for an MCP server segment the session has not asked about, or
 * when the last listing did not settle and neither a repoll is due nor one ran in the last 5 s.
 */
export function ensureMcpAppServers(sessionId, toolName) {
  if (!sessionId) return null;
  const segment = typeof toolName === 'string' ? /^mcp__(.+?)__/.exec(toolName)?.[1] ?? null : null;
  const entry = listings.get(sessionId);
  const stale = entry && !entry.settled && !entry.pending && entry.timer === null && now() - entry.lastAt > MCP_APP_WARM_REPOLL_MS;
  if (entry && !stale && (!segment || entry.segments.has(segment))) return entry.pending;
  if (stale) entry.attempt = 0;
  const pending = listServers(sessionId);
  if (segment) listings.get(sessionId)?.segments.add(segment);
  return pending;
}

// ---- model context: the widgets' ui/update-model-context states go out with the session's next send.
/**
 * The composer's send (main.jsx): the session's widget model context (the card's shared-28 store, official
 * getModelContextStates) to MA-4 mcp-app:tool-states, only when a widget shared something (c6b8adeaf
 * `f.length>0 ? f : void 0`; GrowthBook __gb__3756952893 is off in the host, so nothing is filtered or removed after
 * the send). No card has loaded yet → no widget can have shared anything. Never throws; resolves with the reply or null.
 */
export async function noteMcpAppSendContext(sessionId) {
  const call = desktopCall();
  if (!call || !sessionId || !cardModule) return null;
  try {
    const { Ha: modelContext } = await import('./generated/mcp-app-card/shared-28.mjs');
    const states = modelContext.getState().getModelContextStates(sessionId);
    if (!Array.isArray(states) || states.length === 0) return null;
    return await call('mcp-app:tool-states', { sessionId, toolStates: states });
  } catch (error) {
    console.warn('[MCP App] model context not sent', error?.message ?? error);
    return null;
  }
}

// ---- approvals: the host's pending approvals of MCP App calls, by session (kQe waits while one is pending).
const approvals = new Map(); // sessionId → Map(itemId → {status, toolName})
function setRowApproval(sessionId, itemId, toolName, pending) {
  const rows = approvals.get(sessionId) ?? new Map();
  const had = rows.has(itemId);
  if (pending) rows.set(itemId, { status: 'pending', toolName }); else rows.delete(itemId);
  if (!pending && !had) return;
  if (rows.size) approvals.set(sessionId, rows); else approvals.delete(sessionId);
  mcpAppCardHost.setToolApprovals(Object.fromEntries([...approvals].map(([id, requests]) => [id, Object.fromEntries(requests)])));
}

// ---- the composer each session's transcript fills (official onPrefillComposer, H_ in c10f0af0c).
const prefillers = new Map(); // sessionId → {current: fn}

// ---- nested transcripts: a subagent's thread is no session of its own (R4i-mcp fix).
// The core's child threads never join config.threadIds (main.cjs lists only threads without parentThreadId), so
// mcp-apps-host's known() (main.cjs agentToolSession) refuses them. The official subagent rows belong to the parent
// session's transcript (one sessionRef for the card, the servers and the model context), so a nested view's rows
// classify, list servers and draw their cards under the session that owns the subagent.
const nestedOwners = new Map(); // child thread id → owning session id
const MAX_NESTED_OWNERS = 512;
/** A nested view's child thread → its owning session (idempotent; a self or empty owner is ignored). */
function noteNestedOwner(childId, ownerId) {
  if (typeof childId !== 'string' || !childId || typeof ownerId !== 'string' || !ownerId || childId === ownerId) return;
  if (nestedOwners.get(childId) === ownerId) return;
  nestedOwners.delete(childId);
  nestedOwners.set(childId, ownerId);
  while (nestedOwners.size > MAX_NESTED_OWNERS) nestedOwners.delete(nestedOwners.keys().next().value);
}
/** The session whose MCP App state a row of `sessionId` uses: its owner, transitively (a subagent's subagent), else itself. */
export function mcpAppSessionOf(sessionId) {
  let id = sessionId ?? null;
  for (let hops = 0; id && nestedOwners.has(id) && hops < 16; hops += 1) id = nestedOwners.get(id);
  return id;
}

/** The session's MCP App tool matcher (cef1e6037 lt over the adapters' server state). */
function useMcpAppToolMatcher(sessionId) {
  const state = useSessionMcpState(sessionId ?? undefined);
  return useMemo(() => name => typeof name === 'string' && name.startsWith('mcp__') && !!findMcpAppToolServer(name, state), [state]);
}

/**
 * main.jsx: the open session's MCP App rows. `group(groupFn, items, …args)` runs the transcript's tool grouping around
 * the MCP App rows (KBe "mcp_app", UV stands-alone); onPrefillComposer(text) → boolean fills that session's composer.
 */
export function useMcpAppTranscript({ sessionId, onPrefillComposer }) {
  const isMcpAppTool = useMcpAppToolMatcher(sessionId);
  const prefill = useRef(onPrefillComposer);
  prefill.current = onPrefillComposer;
  useEffect(() => {
    if (!sessionId) return;
    prefillers.set(sessionId, prefill);
    return () => { if (prefillers.get(sessionId) === prefill) prefillers.delete(sessionId); };
  }, [sessionId]);
  return useMemo(() => {
    const isMcpAppItem = item => mcpAppRowKind(item, isMcpAppTool) === MCP_APP_ROW;
    return { isMcpAppTool, isMcpAppItem, group: (groupFn, items, ...args) => groupAroundMcpAppRows(groupFn, items, isMcpAppItem, ...args) };
  }, [isMcpAppTool]);
}

/**
 * A nested transcript (a subagent's view in source-agent.jsx, the side chat in source-btw-pane.jsx): `group(groupFn,
 * items, …args)` runs that view's tool grouping around the MCP App rows of `sessionId` (KBe "mcp_app", UV stands-alone),
 * as the session transcript does. The official nested views draw their tool items with the same _4e → sG → QV/KBe
 * classification (c96d752d0), so an App call is its own row there too. `ownerId` (a subagent's view): the session
 * that owns the child thread `sessionId`; its MCP App state classifies the rows and draws their cards.
 */
export function useMcpAppRowGrouping(sessionId, ownerId = null) {
  noteNestedOwner(sessionId, ownerId); // before the rows render (they resolve their sessionKey through it)
  const isMcpAppTool = useMcpAppToolMatcher(mcpAppSessionOf(sessionId));
  return useMemo(() => {
    const isMcpAppItem = item => mcpAppRowKind(item, isMcpAppTool) === MCP_APP_ROW;
    return (groupFn, items, ...args) => groupAroundMcpAppRows(groupFn, items, isMcpAppItem, ...args);
  }, [isMcpAppTool]);
}

/**
 * One MCP call row of the transcript: the generated card (VX) when the call's tool is an MCP App tool of the session,
 * else `fallback`, the host's own row. The card's root carries no transcript anchor, so a drawn card sits in a
 * source-message row with the item id (find, scroll, copy and chapters locate rows by data-transcript-item-id).
 */
export function SourceMcpAppRow({ item, sessionKey: rowSession = null, awaitingApproval = false, turnStart = false, fallback = null }) {
  const sessionKey = mcpAppSessionOf(rowSession); // a subagent's row: the owning session (nestedOwners)
  const name = officialToolName(item);
  const isMcpAppTool = useMcpAppToolMatcher(sessionKey);
  const isApp = !!sessionKey && name !== null && isMcpAppTool(name);
  useEffect(() => { if (sessionKey && name) ensureMcpAppServers(sessionKey, name); }, [sessionKey, name]);
  useEffect(() => {
    if (!isApp) return undefined;
    setRowApproval(sessionKey, item.id, name, awaitingApproval);
    return () => setRowApproval(sessionKey, item.id, name, false);
  }, [isApp, sessionKey, item.id, name, awaitingApproval]);
  const Card = useCardModule(isApp);
  const sessionRef = useMemo(() => (sessionKey ? { type: 'local', id: sessionKey } : null), [sessionKey]);
  const onPrefillComposer = useMemo(() => text => {
    const fill = prefillers.get(sessionKey)?.current;
    return typeof fill === 'function' ? fill(text) === true : false;
  }, [sessionKey]);
  if (!isApp || !Card) return fallback;
  return <div className="source-message source-mcp-app-row" data-transcript-item-id={item.id} data-mcp-app-row="" data-turn-start={turnStart || undefined}>
    <Card.McpAppToolCard tool={toMcpAppTool(item, { awaitingApproval })} sessionRef={sessionRef} onPrefillComposer={onPrefillComposer} fallback={fallback} />
  </div>;
}

/** Whether a transcript item is an MCP call (the only items SourceMcpAppRow is mounted for). */
export function isMcpCallItem(item) { return mcpCallOf(item) !== null; }

/** Tests: forget listings, approvals, composers and the card adapters' state. */
export const mcpAppTranscriptHost = Object.freeze({
  reset() {
    for (const entry of listings.values()) if (entry.timer !== null) clearTimeout(entry.timer);
    listings.clear(); approvals.clear(); prefillers.clear(); nestedOwners.clear();
    mcpAppCardHost.reset();
  },
});
